  document.addEventListener('keydown', event => { if (!state.summary || state.tab !== 'replay' || /INPUT|SELECT|TEXTAREA|BUTTON/.test(event.target.tagName)) return; if (event.code === 'Space') { event.preventDefault(); togglePlay(); } else if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') { event.preventDefault(); seek(state.cursor + (event.key === 'ArrowRight' ? 1 : -1) * (event.shiftKey ? 10000 : 1000)); } else if (event.key === 'Home') { event.preventDefault(); seek(state.start); } else if (event.key === 'End') { event.preventDefault(); seek(state.end); } });
