  document.addEventListener('dragenter', event => { if (!Array.from(event.dataTransfer?.types || []).includes('Files')) return; event.preventDefault(); dragDepth++; shown('dropOverlay', true); }); document.addEventListener('dragover', event => { if (Array.from(event.dataTransfer?.types || []).includes('Files')) { event.preventDefault(); event.dataTransfer.dropEffect = 'copy'; } }); document.addEventListener('dragleave', event => { event.preventDefault(); if (--dragDepth <= 0) { dragDepth = 0; shown('dropOverlay', false); } }); document.addEventListener('drop', event => { event.preventDefault(); dragDepth = 0; shown('dropOverlay', false); if (event.dataTransfer?.files?.length) openFiles(Array.from(event.dataTransfer.files)); });
